 58| export class ReportService {
 59|   constructor(
 60|     private readonly sessions: SessionRepository,
 61|     private readonly bookings: BookingRepository,
 62|     private readonly now: () => number = Date.now,
 63|   ) {}
 64| 
 65|   /** Report for the 7 days starting at weekStart, or for an explicit from/to range. */
 66|   weekly(query: { weekStart?: unknown; from?: unknown; to?: unknown }): WeeklyReport {
 67|     let from: string;
 68|     let to: string;
 69|     if (query.from !== undefined || query.to !== undefined) {
 70|       from = parseDate(query.from, "from");
 71|       to = parseDate(query.to, "to");
 72|     } else if (query.weekStart !== undefined) {
 73|       from = parseDate(query.weekStart, "weekStart");
 74|       to = addDays(from, 6);
 75|     } else {
 76|       // default: the last complete Monday-to-Sunday week
 77|       const today = new Date(this.now()).toISOString().slice(0, 10);
 78|       const dow = (new Date(Date.parse(today)).getUTCDay() + 6) % 7; // Monday = 0
 79|       from = addDays(today, -dow - 7);
 80|       to = addDays(from, 6);
 81|     }
 82|     if (to < from) throw new DomainError(400, "to must not be before from");
 83|     if ((Date.parse(to) - Date.parse(from)) / DAY_MS > MAX_RANGE_DAYS)
 84|       throw new DomainError(400, `range must not exceed ${MAX_RANGE_DAYS} days`);
 85| 
 86|     const totals: WeeklyReport["totals"] = {
 87|       sessions: 0, ticketsSold: 0, membersAdmitted: 0, occupancy: 0,
 88|       hireIncomeCentsBySize: {}, refundedBookings: 0, refundedCents: 0,
 89|       sessionsOnHold: 0, sessionsCancelled: 0,
 90|     };
 91|     let totalCapacity = 0;
 92|     const rows: SessionReportRow[] = [];
 93|     for (const s of this.sessions.findBetween(from, to)) {
 94|       const row: SessionReportRow = {
 95|         sessionId: s.id, date: s.date, start: s.start, end: s.end, status: s.status,
 96|         capacity: s.capacity, ticketsSold: 0, membersAdmitted: 0, occupancy: 0,
 97|         hireIncomeCentsBySize: {}, refundedBookings: 0, refundedCents: 0,
 98|       };
 99|       for (const b of this.bookings.findBySession(s.id)) {
100|         if (b.status === "paid") {
101|           if (b.membershipNumber) row.membersAdmitted += b.tickets;
102|           else row.ticketsSold += b.tickets;
103|           for (const [size, qty] of Object.entries(b.hire)) {
104|             addTo(row.hireIncomeCentsBySize, size, qty * HIRE_PRICE_CENTS);
105|             addTo(totals.hireIncomeCentsBySize, size, qty * HIRE_PRICE_CENTS);
106|           }
107|         } else if (b.status === "refunded") {
108|           row.refundedBookings++;
109|           row.refundedCents += b.amountCents;
110|         }
111|       }
112|       row.occupancy = s.capacity > 0 ? (row.ticketsSold + row.membersAdmitted) / s.capacity : 0;
113|       rows.push(row);
114|       totals.sessions++;
115|       totals.ticketsSold += row.ticketsSold;
116|       totals.membersAdmitted += row.membersAdmitted;
117|       totals.refundedBookings += row.refundedBookings;
118|       totals.refundedCents += row.refundedCents;
119|       totalCapacity += s.capacity;
120|       if (s.status === "on-hold") totals.sessionsOnHold++;
121|       if (s.status === "cancelled") totals.sessionsCancelled++;
122|     }
123|     totals.occupancy = totalCapacity > 0 ? (totals.ticketsSold + totals.membersAdmitted) / totalCapacity : 0;
124|     return { from, to, sessions: rows, totals };
125|   }
126| }
